import 'package:flutter/material.dart';
import 'package:geolocator/geolocator.dart';
import 'package:go_router/go_router.dart';

import '../../core/localization/app_strings.dart';
import '../../core/theme/app_colors.dart';

class LocationPermissionScreen extends StatefulWidget {const LocationPermissionScreen({super.key});@override State<LocationPermissionScreen> createState()=>_LocationPermissionScreenState();}
class _LocationPermissionScreenState extends State<LocationPermissionScreen>{bool loading=false;String? error;Future<void> allow()async{setState((){loading=true;error=null;});try{final enabled=await Geolocator.isLocationServiceEnabled();if(!enabled){setState(()=>error=AppStrings.of(context).t('gpsDisabled'));return;}var p=await Geolocator.checkPermission();if(p==LocationPermission.denied)p=await Geolocator.requestPermission();if(p==LocationPermission.denied||p==LocationPermission.deniedForever){setState(()=>error=AppStrings.of(context).t('locationDenied'));return;}await Geolocator.getCurrentPosition();if(mounted)context.go('/permissions/notifications');}catch(_){if(mounted)setState(()=>error=AppStrings.of(context).t('errorGeneric'));}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext context){final s=AppStrings.of(context);return Scaffold(body:SafeArea(child:Padding(padding:const EdgeInsets.all(24),child:Column(children:[const Spacer(),Container(width:150,height:150,decoration:BoxDecoration(color:AppColors.blue.withValues(alpha:.07),borderRadius:BorderRadius.circular(44)),child:const Icon(Icons.location_on_rounded,size:72,color:AppColors.blue)),const SizedBox(height:34),Text(s.t('yourLocation'),textAlign:TextAlign.center,style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:12),Text(s.t('locationBody'),textAlign:TextAlign.center,style:Theme.of(context).textTheme.bodyLarge?.copyWith(color:AppColors.muted)),if(error!=null)...[const SizedBox(height:18),Text(error!,textAlign:TextAlign.center,style:const TextStyle(color:AppColors.danger))],const Spacer(),SizedBox(width:double.infinity,height:56,child:FilledButton(onPressed:loading?null:allow,child:loading?const SizedBox.square(dimension:20,child:CircularProgressIndicator(strokeWidth:2,color:Colors.white)):Text(s.t('allowLocation')))),const SizedBox(height:10),TextButton(onPressed:()=>context.push('/manual-address'),child:Text(s.t('manualLocation')))]))));}}